import java.lang.annotation.*;
@Target(ElementType.TYPE_USE) @interface A { int value() default 0; }
@Target(ElementType.TYPE_USE) @interface B {}
class Coverage { int f(Object @A @B ... values) { int n = 0; for (Object value : values) { if (value != null) n++; } return n; } }

import java.lang.annotation.*;
@Target(ElementType.TYPE_USE) @interface A { int value() default 0; }
@Target(ElementType.TYPE_USE) @interface B {}
class Coverage { Coverage(String @A(1 + 2) ... values) { if (values == null) throw new IllegalArgumentException(); } }

import java.lang.annotation.*;
@Target(ElementType.TYPE_USE) @interface A { int value() default 0; }
@Target(ElementType.TYPE_USE) @interface B {}
class Coverage { int f(String @A [] @B ... values) { return values.length > 0 ? values[0].length : 0; } }

import java.lang.annotation.*;
@Target(ElementType.TYPE_USE) @interface A { int value() default 0; }
@Target(ElementType.TYPE_USE) @interface B {}
record Coverage(String @A ... values) { Coverage { if (values == null) throw new IllegalArgumentException(); } }

import java.lang.annotation.*;
@Target(ElementType.TYPE_USE) @interface A { int value() default 0; }
@Target(ElementType.TYPE_USE) @interface B {}
record Pair(String text) {}
class Coverage { int f(Object value) { if (value instanceof Pair(@A String text)) return text.length(); return 0; } }

import java.lang.annotation.*;
@Target(ElementType.TYPE_USE) @interface A { int value() default 0; }
@Target(ElementType.TYPE_USE) @interface B {}
class Coverage { void risk() throws java.io.IOException, ReflectiveOperationException {} int f() { try { risk(); return 0; } catch (java.io.IOException | @A ReflectiveOperationException error) { return 1; } } }

import java.lang.annotation.*;
@Target(ElementType.TYPE_USE) @interface A { int value() default 0; }
@Target(ElementType.TYPE_USE) @interface B {}
record Pair(String text) {} class Coverage { int f(Object value) { if (value instanceof Pair(final String text)) return text.length(); return switch (value) { case @A String text -> text.length(); case final Integer number -> number; default -> 0; }; } }
